// Package store persists domain entities in Postgres (D13, D19). Queries are
// generated by sqlc into internal/store/db; this package maps them to domain types.
package store

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/misarescu/frankie/internal/domain"
	"github.com/misarescu/frankie/internal/store/db"
)

var (
	// ErrNotFound means the requested row does not exist.
	ErrNotFound = errors.New("store: not found")
	// ErrConflict means a uniqueness rule or a concurrent status change prevented the write.
	ErrConflict = errors.New("store: conflict")
)

// Store is the Postgres-backed repository for domain entities.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Open connects to Postgres and verifies the connection. It does not run migrations.
func Open(ctx context.Context, databaseURL string) (*Store, error) {
	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return nil, fmt.Errorf("store: open pool: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("store: ping: %w", err)
	}
	return New(pool), nil
}

// New wraps an existing pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}

// Pool exposes the underlying pool, e.g. for Migrate.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// Close releases all connections.
func (s *Store) Close() { s.pool.Close() }

// inTx runs fn in a transaction, committing on success.
func (s *Store) inTx(ctx context.Context, fn func(q *db.Queries) error) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("store: begin: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }() // no-op after commit
	if err := fn(s.q.WithTx(tx)); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("store: commit: %w", err)
	}
	return nil
}

// mapErr turns driver errors into store sentinels, keeping the original in the chain.
func mapErr(op string, err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) {
		return fmt.Errorf("store: %s: %w", op, ErrNotFound)
	}
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == "23505" { // unique_violation
		return fmt.Errorf("store: %s: %w (%s)", op, ErrConflict, pgErr.ConstraintName)
	}
	return fmt.Errorf("store: %s: %w", op, err)
}

// appendStateChange records a status change in the event stream (FR-WF-7).
func appendStateChange(ctx context.Context, q *db.Queries, runID, stepRunID *uuid.UUID, change domain.StateChange) error {
	payload, err := json.Marshal(change)
	if err != nil {
		return fmt.Errorf("store: marshal state change: %w", err)
	}
	_, err = q.AppendEvent(ctx, db.AppendEventParams{
		ID:        domain.NewID(),
		RunID:     runID,
		StepRunID: stepRunID,
		Ts:        time.Now().UTC(),
		Type:      string(domain.EventStateChange),
		Payload:   payload,
	})
	return mapErr("append state change", err)
}

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func nonEmpty(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

func nonNil[T any](s []T) []T {
	if s == nil {
		return []T{}
	}
	return s
}
